    call(10, 10);
} catch (RateLimitException e) {
    caught = e;
}
check(caught != null);
checkEq(caught.limit(), 10);
checkEq(caught.retryAfterSeconds(), 1);
checkEq(caught.getMessage(), "rate limit of 10 requests exceeded, retry in 1 seconds");

